use std::collections::{BTreeMap, HashMap};
use std::env;

#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
enum Symbol {
    Char(char),
}

impl Symbol {
    fn to_string(&self) -> String {
        match self {
            Symbol::Char(c) => {
                if "*+?.()[]{}|^$\\".contains(*c) {
                    format!("\\{}", c)
                } else {
                    c.to_string()
                }
            }
        }
    }
}

struct State {
    transitions: BTreeMap<Symbol, usize>,
    is_accepting: bool,
}

struct Trie {
    states: Vec<State>,
}

impl Trie {
    fn new() -> Self {
        Trie {
            states: vec![State {
                transitions: BTreeMap::new(),
                is_accepting: false,
            }],
        }
    }

    fn add_string(&mut self, s: &str) {
        let mut current_state = 0;
        for c in s.chars() {
            let symbol = Symbol::Char(c);
            if !self.states[current_state].transitions.contains_key(&symbol) {
                let new_state = self.states.len();
                self.states.push(State {
                    transitions: BTreeMap::new(),
                    is_accepting: false,
                });
                self.states[current_state].transitions.insert(symbol.clone(), new_state);
            }
            current_state = *self.states[current_state].transitions.get(&symbol).unwrap();
        }
        self.states[current_state].is_accepting = true;
    }
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    if args.is_empty() {
        return;
    }

    let mut trie = Trie::new();
    for arg in args {
        trie.add_string(&arg);
    }

    // Simple RE generation without minimization for now
    let re = generate_re(&trie, 0);
    println!("^{}$", re);
}

fn generate_re(trie: &Trie, state_idx: usize) -> String {
    let state = &trie.states[state_idx];
    if state.transitions.is_empty() {
        return "".to_string();
    }

    let mut terms: Vec<String> = Vec::new();
    for (symbol, &next_state) in &state.transitions {
        let suffix = generate_re(trie, next_state);
        terms.push(format!("{}{}", symbol.to_string(), suffix));
    }

    let mut res = if terms.len() > 1 {
        format!("(?:{})", terms.join("|"))
    } else {
        terms[0].clone()
    };

    if state.is_accepting {
        res = format!("{}?", res); // This is not quite right for all cases
    }
    res
}
