{"command":"cat <<'EOF' > src/main.rs
use std::collections::{BTreeMap, HashMap};
use std::env;

#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
enum Symbol {
    Char(char),
}

impl Symbol {
    fn to_string(&self) -> String {
        match self {
            Symbol::Char(c) => {
                if "*+?.()[]{}|^$\\".contains(*c) {
                    format!("\\{}", c)
                } else {
                    c.to_string()
                }
            }
        }
    }
}

struct Trie {
    states: Vec<TrieState>,
}

struct TrieState {
    transitions: BTreeMap<char, usize>,
    is_accepting: bool,
}

impl Trie {
    fn new() -> Self {
        Trie {
            states: vec![TrieState {
                transitions: BTreeMap::new(),
                is_accepting: false,
            }],
        }
    }

    fn add_string(&mut self, s: &str) {
        let mut curr = 0;
        for c in s.chars() {
            if !self.states[curr].transitions.contains_key(&c) {
                let next = self.states.len();
                self.states.push(TrieState {
                    transitions: BTreeMap::new(),
                    is_accepting: false,
                });
                self.states[curr].transitions.insert(c, next);
            }
            curr = self.states[curr].transitions[&c];
        }
        self.states[curr].is_accepting = true;
    }
}

struct DFA {
    states: Vec<DFAState>,
    start_state: usize,
}

struct DFAState {
    transitions: BTreeMap<usize, Vec<char>>, // next_state -> symbols
    is_accepting: bool,
}

fn minimize(trie: &Trie) -> DFA {
    let mut state_to_id: HashMap<(bool, BTreeMap<char, usize>), usize> = HashMap::new();
    let mut old_to_new: HashMap<usize, usize> = HashMap::new();

    // Since it's a Trie, we can process states in reverse order of creation
    // to ensure we process children before parents.
    for i in (0..trie.states.len()).rev() {
        let state = &trie.states[i];
        let mut new_transitions = BTreeMap::new();
        for (&c, &next) in &state.transitions {
            new_transitions.insert(c, old_to_new[&next]);
        }
        let key = (state.is_accepting, new_transitions);
        let id = if let Some(&id) = state_to_id.get(&key) {
            id
        } else {
            let id = state_to_id.len();
            state_to_id.insert(key, id);
            id
        };
        old_to_new.insert(i, id);
    }

    let mut new_states = vec![(); state_to_id.len()];
    let mut dfa_states = Vec::new();
    for _ in 0..state_to_id.len() {
        dfa_states.push(DFAState {
            transitions: BTreeMap::new(),
            is_accepting: false,
        });
    }

    for ((is_accepting, transitions), &id) in &state_to_id {
        dfa_states[id].is_accepting = *is_accepting;
        for (&c, &next_id) in transitions {
            dfa_states[id].transitions.entry(next_id).or_default().push(c);
        }
    }

    DFA {
        states: dfa_states,
        start_state: old_to_new[&0],
    }
}

fn format_char_class(mut chars: Vec<char>) -> String {
    if chars.len() == 1 {
        let c = chars[0];
        if "*+?.()[]{}|^$\\".contains(c) {
            return format!("\\{}", c);
        } else {
            return c.to_string();
        }
    }
    chars.sort();
    let mut res = String::from("[");
    let mut i = 0;
    while i < chars.len() {
        let mut j = i;
        while j + 1 < chars.len() && (chars[j+1] as u32) == (chars[j] as u32) + 1 {
            j += 1;
        }
        if j - i >= 2 {
            res.push_str(&format_char(chars[i]));
            res.push('-');
            res.push_str(&format_char(chars[j]));
            i = j + 1;
        } else {
            res.push_str(&format_char(chars[i]));
            i += 1;
        }
    }
    res.push(']');
    res
}

fn format_char(c: char) -> String {
    if "[]\\^-".contains(c) {
        format!("\\{}", c)
    } else if c == '$' {
        "\\$".to_string() // grex seems to escape $ in char classes
    } else {
        c.to_string()
    }
}

fn generate_re(dfa: &DFA, state_idx: usize, memo: &mut HashMap<usize, String>) -> String {
    if let Some(res) = memo.get(&state_idx) {
        return res.clone();
    }

    let state = &dfa.states[state_idx];
    let mut terms = Vec::new();
    for (&next_state, chars) in &state.transitions {
        let char_class = format_char_class(chars.clone());
        let suffix = generate_re(dfa, next_state, memo);

        // Wrap char_class if it's more than one char and suffix is not empty
        // Actually, format_char_class already returns [...] or a single char.
        // If it's [...], we don't need to wrap it in (?:...) unless it's followed by something.
        // But if suffix is not empty, concatenation is fine.
        terms.push(format!("{}{}", char_class, suffix));
    }

    // Sort terms by matched length descending, then alphabetical.
    // For now, just sort alphabetical.
    terms.sort_by(|a, b| b.len().cmp(&a.len()).then(a.cmp(b)));

    let mut res = if terms.len() > 1 {
        format!("(?:{})", terms.join("|"))
    } else if terms.len() == 1 {
        terms[0].clone()
    } else {
        "".to_string()
    };

    if state.is_accepting && state_idx != dfa.start_state {
        // This is tricky. Optionality should be handled by the parent.
    }

    memo.insert(state_idx, res.clone());
    res
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    if args.is_empty() { return; }
    let mut trie = Trie::new();
    for arg in args {
        if !arg.starts_with('-') { trie.add_string(&arg); }
    }
    let dfa = minimize(&trie);
    let mut memo = HashMap::new();
    let re = generate_re(&dfa, dfa.start_state, &mut memo);
    println!("^{}$", re);
}
