use std::collections::{BTreeMap, HashMap};
use std::env;
use std::fs::File;
use std::io::{self, BufRead};

#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
enum Symbol {
    Digit,
    Whitespace,
    Word,
    NonDigit,
    NonWhitespace,
    NonWord,
    Char(char),
}

impl Symbol {
    fn to_string(&self) -> String {
        match self {
            Symbol::Digit => "\\d".to_string(),
            Symbol::Whitespace => "\\s".to_string(),
            Symbol::Word => "\\w".to_string(),
            Symbol::NonDigit => "\\D".to_string(),
            Symbol::NonWhitespace => "\\S".to_string(),
            Symbol::NonWord => "\\W".to_string(),
            Symbol::Char(c) => {
                if "*+?.()[]{}|^$\\".contains(*c) {
                    format!("\\{}", c)
                } else {
                    c.to_string()
                }
            }
        }
    }
}

struct Flags {
    digits: bool,
    non_digits: bool,
    spaces: bool,
    non_spaces: bool,
    words: bool,
    non_words: bool,
    no_start_anchor: bool,
    no_end_anchor: bool,
    escape: bool,
}

impl Flags {
    fn from_args(args: &[String]) -> (Self, Vec<String>) {
        let mut flags = Flags {
            digits: false,
            non_digits: false,
            spaces: false,
            non_spaces: false,
            words: false,
            non_words: false,
            no_start_anchor: false,
            no_end_anchor: false,
            escape: false,
        };
        let mut inputs = Vec::new();
        let mut skip_next = false;
        for (i, arg) in args.iter().enumerate() {
            if skip_next {
                skip_next = false;
                continue;
            }
            if arg == "-d" || arg == "--digits" { flags.digits = true; }
            else if arg == "-D" || arg == "--non-digits" { flags.non_digits = true; }
            else if arg == "-s" || arg == "--spaces" { flags.spaces = true; }
            else if arg == "-S" || arg == "--non-spaces" { flags.non_spaces = true; }
            else if arg == "-w" || arg == "--words" { flags.words = true; }
            else if arg == "-W" || arg == "--non-words" { flags.non_words = true; }
            else if arg == "--no-start-anchor" { flags.no_start_anchor = true; }
            else if arg == "--no-end-anchor" { flags.no_end_anchor = true; }
            else if arg == "--no-anchors" { flags.no_start_anchor = true; flags.no_end_anchor = true; }
            else if arg == "-e" || arg == "--escape" { flags.escape = true; }
            else if arg == "-f" || arg == "--file" {
                if let Some(file_path) = args.get(i + 1) {
                    if file_path == "-" {
                        let stdin = io::stdin();
                        for line in stdin.lock().lines() {
                            if let Ok(l) = line { if !l.is_empty() { inputs.push(l); } }
                        }
                    } else {
                        let file = File::open(file_path).unwrap();
                        let reader = io::BufReader::new(file);
                        for line in reader.lines() {
                            if let Ok(l) = line { if !l.is_empty() { inputs.push(l); } }
                        }
                    }
                    skip_next = true;
                }
            }
            else if !arg.starts_with('-') {
                inputs.push(arg.clone());
            } else if arg == "-" {
                let stdin = io::stdin();
                for line in stdin.lock().lines() {
                    if let Ok(l) = line { if !l.is_empty() { inputs.push(l); } }
                }
            }
        }
        (flags, inputs)
    }
}

fn get_symbol(c: char, flags: &Flags) -> Symbol {
    if flags.digits && c.is_numeric() { return Symbol::Digit; }
    if flags.spaces && c.is_whitespace() { return Symbol::Whitespace; }
    if flags.words && (c.is_alphanumeric() || c == '_') { return Symbol::Word; }
    if flags.non_digits && !c.is_numeric() { return Symbol::NonDigit; }
    if flags.non_spaces && !c.is_whitespace() { return Symbol::NonWhitespace; }
    if flags.non_words && !(c.is_alphanumeric() || c == '_') { return Symbol::NonWord; }
    Symbol::Char(c)
}

struct TrieState {
    transitions: BTreeMap<Symbol, usize>,
    is_accepting: bool,
}

struct Trie {
    states: Vec<TrieState>,
}

impl Trie {
    fn new() -> Self {
        Trie {
            states: vec![TrieState { transitions: BTreeMap::new(), is_accepting: false }],
        }
    }

    fn add_string(&mut self, s: &str, flags: &Flags) {
        let mut curr = 0;
        for c in s.chars() {
            let sym = get_symbol(c, flags);
            if !self.states[curr].transitions.contains_key(&sym) {
                let next = self.states.len();
                self.states.push(TrieState { transitions: BTreeMap::new(), is_accepting: false });
                self.states[curr].transitions.insert(sym.clone(), next);
            }
            curr = self.states[curr].transitions[&sym];
        }
        self.states[curr].is_accepting = true;
    }
}

struct DFAState {
    transitions: BTreeMap<usize, Vec<Symbol>>,
    is_accepting: bool,
}

struct DFA {
    states: Vec<DFAState>,
    start_state: usize,
}

fn minimize(trie: &Trie) -> DFA {
    let mut state_to_id: HashMap<(bool, BTreeMap<Symbol, usize>), usize> = HashMap::new();
    let mut old_to_new: HashMap<usize, usize> = HashMap::new();
    for i in (0..trie.states.len()).rev() {
        let state = &trie.states[i];
        let mut new_transitions = BTreeMap::new();
        for (sym, &next) in &state.transitions {
            new_transitions.insert(sym.clone(), old_to_new[&next]);
        }
        let key = (state.is_accepting, new_transitions);
        let id = *state_to_id.entry(key).or_insert_with(|| state_to_id.len());
        old_to_new.insert(i, id);
    }
    let mut dfa_states = (0..state_to_id.len()).map(|_| DFAState { transitions: BTreeMap::new(), is_accepting: false }).collect::<Vec<_>>();
    for ((is_acc, transitions), &id) in &state_to_id {
        dfa_states[id].is_accepting = *is_acc;
        for (sym, &next_id) in transitions {
            dfa_states[id].transitions.entry(next_id).or_default().push(sym.clone());
        }
    }
    DFA { states: dfa_states, start_state: old_to_new[&0] }
}

fn format_symbols(mut syms: Vec<Symbol>, flags: &Flags) -> String {
    if syms.len() == 1 { return syms[0].to_string(); }
    let mut chars = Vec::new();
    let mut classes = Vec::new();
    for s in syms {
        match s {
            Symbol::Char(c) => chars.push(c),
            _ => classes.push(s.to_string()),
        }
    }
    if classes.is_empty() { return format_char_class(chars); }
    if chars.is_empty() {
        if classes.len() == 1 { return classes[0].clone(); }
        return format!("(?:{})", classes.join("|"));
    }
    let mut res = format!("(?:{}|{})", classes.join("|"), format_char_class(chars));
    res
}

fn format_char_class(mut chars: Vec<char>) -> String {
    if chars.len() == 1 {
        let c = chars[0];
        return if "*+?.()[]{}|^$\\".contains(c) { format!("\\{}", c) } else { c.to_string() };
    }
    chars.sort();
    let mut res = String::from("[");
    let mut i = 0;
    while i < chars.len() {
        let mut j = i;
        while j + 1 < chars.len() && (chars[j+1] as u32) == (chars[j] as u32) + 1 { j += 1; }
        if j - i >= 2 {
            res.push_str(&format_char(chars[i]));
            res.push('-');
            res.push_str(&format_char(chars[j]));
            i = j + 1;
        } else {
            res.push_str(&format_char(chars[i]));
            i += 1;
        }
    }
    res.push(']');
    res
}

fn format_char(c: char) -> String {
    if "[]\\^-".contains(c) { format!("\\{}", c) } else if c == '$' { "\\$".to_string() } else { c.to_string() }
}

fn generate_re(dfa: &DFA, state_idx: usize, memo: &mut HashMap<usize, String>, flags: &Flags) -> String {
    if let Some(res) = memo.get(&state_idx) { return res.clone(); }
    let state = &dfa.states[state_idx];
    let mut terms = Vec::new();
    for (&next_state, syms) in &state.transitions {
        let sym_str = format_symbols(syms.clone(), flags);
        let suffix = generate_re(dfa, next_state, memo, flags);
        terms.push(format!("{}{}", sym_str, suffix));
    }
    terms.sort_by(|a, b| b.len().cmp(&a.len()).then(a.cmp(b))); // Heuristic for ordering
    let mut res = if terms.len() > 1 {
        let joined = terms.join("|");
        if state.is_accepting { format!("(?:{})?", joined) } else { format!("(?:{})", joined) }
    } else if terms.len() == 1 {
        if state.is_accepting {
            // Need to wrap in (?:) if terms[0] is multiple chars
            if terms[0].chars().count() > 1 && !terms[0].starts_with('[') && !terms[0].starts_with('( ') {
                 format!("(?:{})?", terms[0])
            } else {
                 format!("{}?", terms[0])
            }
        } else {
            terms[0].clone()
        }
    } else { "".to_string() };
    memo.insert(state_idx, res.clone());
    res
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    let (flags, inputs) = Flags::from_args(&args);
    if inputs.is_empty() { return; }
    let mut trie = Trie::new();
    for s in inputs { trie.add_string(&s, &flags); }
    let dfa = minimize(&trie);
    let mut memo = HashMap::new();
    let mut re = generate_re(&dfa, dfa.start_state, &mut memo, &flags);

    // Top-level wrap
    if re.contains('|') && !re.starts_with("(?:") {
        re = format!("(?:{})", re);
    }

    let start = if flags.no_start_anchor { "" } else { "^" };
    let end = if flags.no_end_anchor { "" } else { "$" };
    println!("{}{}{}", start, re, end);
}
