    let mut chars = Vec::new();
    let mut others = Vec::new();
    for s in syms { match s { Symbol::Char(c) => chars.push(c), _ => others.push(s.to_string(flags)) } }
    let mut parts = others;
    if !chars.is_empty() { parts.push(format_char_class(chars, flags)); }
    if parts.len() == 1 { parts[0].clone() } else { format!("(?:{})", parts.join("|")) }
}

fn format_char_class(mut chars: Vec<char>, flags: &Flags) -> String {
    if chars.len() == 1 { return format_char(chars[0], flags, false); }
    chars.sort();
    let mut res = String::from("[");
    let mut i = 0;
    while i < chars.len() {
        let mut j = i;
        while j + 1 < chars.len() && (chars[j+1] as u32) == (chars[j] as u32) + 1 { j += 1; }
        if j - i >= 2 {
            res.push_str(&format_char(chars[i], flags, true)); res.push('-'); res.push_str(&format_char(chars[j], flags, true));
            i = j + 1;
        } else {
            res.push_str(&format_char(chars[i], flags, true)); i += 1;
        }
    }
    res.push(']'); res
}

fn format_char(c: char, flags: &Flags, in_class: bool) -> String {
    if flags.escape && !c.is_ascii() { return format!("\\u{{{:x}}}", c as u32); }
    if in_class {
        if "[]\\^-".contains(c) || c == '$' { format!("\\{}", c) } else { c.to_string() }
    } else {
        if "*+?.()[]{}|^$\\".contains(c) { format!("\\{}", c) } else { c.to_string() }
    }
}

fn generate_re(dfa: &DFA, state_idx: usize, memo: &mut HashMap<usize, String>, flags: &Flags) -> String {
    if let Some(res) = memo.get(&state_idx) { return res.clone(); }
    let state = &dfa.states[state_idx];
    let mut terms = Vec::new();
    for (&next_state, syms) in &state.transitions {
        let sym_str = format_symbols(syms.clone(), flags);
        let suffix = generate_re(dfa, next_state, memo, flags);
        terms.push(format!("{}{}", sym_str, suffix));
    }
    terms.sort_by(|a, b| b.len().cmp(&a.len()).then(a.cmp(b)));
    let mut res = if terms.len() > 1 {
        let joined = terms.join("|");
        if state.is_accepting { format!("(?:{})?", joined) } else { format!("(?:{})", joined) }
    } else if terms.len() == 1 {
        if state.is_accepting {
            if terms[0].chars().count() > 1 && !terms[0].starts_with('[') && !terms[0].starts_with("(?:") {
                format!("(?:{})?", terms[0])
            } else { format!("{}?", terms[0]) }
        } else { terms[0].clone() }
    } else { "".to_string() };
    memo.insert(state_idx, res.clone());
    res
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    let (flags, inputs) = Flags::from_args(&args);
    if inputs.is_empty() { return; }
    let mut trie = Trie::new();
    for s in inputs { trie.add_string(&s, &flags); }
    let dfa = minimize(&trie);
    let mut memo = HashMap::new();
    let mut re = generate_re(&dfa, dfa.start_state, &mut memo, &flags);
    if re.contains('|') && !re.starts_with("(?:") { re = format!("(?:{})", re); }
    let start = if flags.no_start_anchor { "" } else { "^" };
    let end = if flags.no_end_anchor { "" } else { "$" };
    println!("{}{}{}", start, re, end);
}
